package PerCUDA::Engine::Perl;
use v5.40;
use parent 'PerCUDA::Engine';
use Carp         ();
use POSIX        ();
use Storable     ();
use Scalar::Util qw(refaddr);
use PerCUDA::Array;
use PerCUDA::CodeGen::Perl;
use PerCUDA::Data qw(zeros copy_array convert_array is_ndarray);

# Runs the kernel in the perl interpreter, as Perl code generated by
# PerCUDA::CodeGen::Perl.

my $SERIAL = 0;

sub init ($self) {
    my $package = 'PerCUDA::Engine::Perl::Kernel' . $SERIAL++;
    $self->{perl_source} = "package $package;\nuse strict;\nuse warnings;\nno warnings qw(uninitialized numeric);\n"
        . PerCUDA::CodeGen::Perl->new($self->{analyzer}, mode => $self->{mode})->generate;
    $self->{code} = eval $self->{perl_source};    ## no critic (ProhibitStringyEval)
    Carp::croak("PerCUDA: failed to compile the kernel for the perl engine: $@\n$self->{perl_source}")
        unless $self->{code};
    return;
}

sub name ($self) { return 'perl' }

sub perl_source ($self) { return $self->{perl_source} }

sub make_array ($self, $data, $dims, $rank, $type) {
    my $nested  = !defined $data ? zeros($dims) : is_ndarray($data) ? $data->unpdl : $data;
    my $convert = $type eq 'i' || ($type eq 'f' && ($self->{mode} // 'compat') ne 'fast');
    $nested = $convert ? convert_array($nested, $rank, $type) : copy_array($nested, $rank) if defined $data;
    return PerCUDA::Array->_new(engine => 'perl', type => $type, dims => $dims, data => $nested);
}

sub run ($self, @values) {
    my $layout = $self->layout(\@values);
    my @call   = @values;
    my %ndarray_out;    # index => nested array to store back into the caller's ndarray
    for my $i (sort { $a <=> $b } keys %{ $layout->{arrays} }) {
        my $arg = $self->{args}[$i];
        my ($dims, $empty, $ndarray) = @{ $layout->{arrays}{$i} }{qw(dims empty ndarray)};
        my $retval = $self->{is_retval}{ $arg->{name} };

        # A device array holds a nested array already converted to its type,
        # used in place.
        if ($layout->{arrays}{$i}{device}) {
            $call[$i] = $values[$i]{data};
            next;
        }

        # The generated code indexes nested arrays, so an ndarray is unpacked
        # into one (a copy). This is slow, but only on the perl engine.
        my $value = $ndarray && !$empty ? $values[$i]->unpdl : $values[$i];

        # The GPU sees the values as converted to the declared type, and only
        # retval arrays are copied back to the caller.
        my $convert = $arg->{type} eq 'i' || ($arg->{type} eq 'f' && ($self->{mode} // 'compat') ne 'fast');
        my $converted =
              $empty                      ? zeros($dims)
            : $convert                    ? convert_array($value, $arg->{rank}, $arg->{type})
            : $ndarray                    ? $value
            : $arg->{written} && !$retval ? copy_array($value, $arg->{rank})
            :                               undef;
        next unless $converted;
        if ($retval && $ndarray) {
            $call[$i] = $ndarray_out{$i} = $converted;
        }
        elsif ($retval) {
            @{ $values[$i] } = @$converted;    # updated in place, like the GPU engine
        }
        else {
            $call[$i] = $converted;
        }
    }
    my @results = map { $self->{index}{$_} } @{ $self->{retval} };
    if (!$self->_run_parallel(\@call, $layout, \@results)) {
        $self->{code}->(@call, @{ $layout->{grid} });
    }

    for my $i (keys %ndarray_out) {
        my $ndarray = $values[$i];
        my $result  = PDL->pdl($ndarray->type, $ndarray_out{$i});
        $ndarray->reshape(reverse @{ $layout->{arrays}{$i}{dims} });
        $ndarray .= $result;
    }
    return map { $values[$_] } @results;
}

# With perl_jobs > 1, splits the x axis between forked processes, which send
# back their rows of the retval arrays. Only kernels whose stores all use $x
# as the first index qualify, so that the processes never write the same
# element. Rows are dealt out in turn, which balances uneven rows (e.g. the
# Mandelbrot set). Returns false when the kernel has to run in this process.
sub _run_parallel ($self, $call, $layout, $results) {
    my $size_x = $layout->{grid}[0];
    my $jobs   = $self->{jobs} // 1;
    $jobs = $size_x if $jobs > $size_x;
    return 0 if $jobs < 2 || !$self->{analyzer}->writes_own_rows;

    # Arrays whose new contents must survive the run: retval arrays and
    # written device arrays.
    my %kept = map { $_ => 1 } @$results,
        grep { $layout->{arrays}{$_}{device} && $self->{args}[$_]{written} } keys %{ $layout->{arrays} };
    my %seen;
    my $outputs = [ grep { !$seen{ refaddr $_ }++ } map { $call->[$_] } sort { $a <=> $b } keys %kept ];

    my @children;
    for my $job (0 .. $jobs - 1) {
        my @xs = grep { $_ % $jobs == $job } 0 .. $size_x - 1;
        pipe(my $reader, my $writer) or Carp::croak("PerCUDA: pipe failed: $!");
        my $pid = fork // Carp::croak("PerCUDA: fork failed: $!");
        if (!$pid) {
            close $reader;
            my $message = eval {
                $self->{code}->(@$call, @{ $layout->{grid} }, \@xs);
                Storable::freeze([ map { [ @{$_}[@xs] ] } @$outputs ]);
            } // Storable::freeze(\"$@");
            binmode $writer;
            print {$writer} $message;
            close $writer;
            POSIX::_exit(0);    # skip END blocks and destructors of the parent's objects
        }
        close $writer;
        push @children, [ $pid, $reader, \@xs ];
    }

    my $error;
    for my $child (@children) {
        my ($pid, $reader, $xs) = @$child;
        binmode $reader;
        my $message = do { local $/; <$reader> };
        close $reader;
        waitpid $pid, 0;
        my $rows = length $message ? Storable::thaw($message) : \"PerCUDA: a worker process exited unexpectedly";
        if (ref $rows eq 'SCALAR') {
            $error //= $$rows;
            next;
        }
        @{ $outputs->[$_] }[@$xs] = @{ $rows->[$_] } for 0 .. $#$outputs;
    }
    die $error if defined $error;
    return 1;
}

package PerCUDA::Runtime;

sub _f32 ($v) { return unpack 'f', pack 'f', $v }

my $INF = 9**9**9;
my $NAN = -sin($INF);

# IEEE 754 division by zero, as on the GPU: +-inf, or nan for 0/0.
sub div0 ($l, $r) {
    return $NAN if $l == 0 || $l != $l;
    my $negative_zero = unpack('Q', pack('d', $r)) >> 63;
    return ($l < 0) != $negative_zero ? -$INF : $INF;
}

sub div ($l, $r) { return $r != 0 ? $l / $r : div0($l, $r) }

# percuda_mod of the generated CUDA code returns 0 for a zero divisor.
sub mod ($l, $r) { return int($r) ? $l % $r : 0 }

# x ** n by repeated squaring, in the same order and precision as
# percuda_powi_* in the generated CUDA code.
sub powi_f ($x, $n) {
    my ($r, $m) = (1.0, abs int $n);
    while ($m) {
        $r = _f32($r * $x) if $m & 1;
        $x = _f32($x * $x);
        $m >>= 1;
    }
    return $n < 0 ? _f32(1.0 / $r) : $r;
}

sub powi_d ($x, $n) {
    my ($r, $m) = (1.0, abs int $n);
    while ($m) {
        $r *= $x if $m & 1;
        $x *= $x;
        $m >>= 1;
    }
    return $n < 0 ? 1.0 / $r : $r;
}

{
    use integer;

    # Integer operations on 32-bit signed integers, as on the GPU.
    sub _i32 ($v) { return unpack 'l', pack 'L', $v & 0xFFFFFFFF }

    sub band ($l, $r) { return _i32(_i32($l) & _i32($r)) }
    sub bor  ($l, $r) { return _i32(_i32($l) | _i32($r)) }
    sub bxor ($l, $r) { return _i32(_i32($l) ^ _i32($r)) }
    sub bnot ($v)     { return _i32(~_i32($v)) }
    sub shl  ($l, $r) { return _i32(_i32($l) << _i32($r)) }
    sub shr  ($l, $r) { return _i32($l) >> _i32($r) }

    sub powi_i ($x, $n) {
        my $r = 1;
        $x = _i32($x);
        while ($n > 0) {
            $r = _i32($r * $x) if $n & 1;
            $x = _i32($x * $x);
            $n >>= 1;
        }
        return $r;
    }
}

1;
